let words = null;
let buckets = null;

function load() {
  if (words) return words;
  const set = new Set();
  let prev = '';
  for (const line of PACK.split('\n')) {
    if (!line) continue;
    const code = line.charCodeAt(0);
    const word = code >= 50 && code <= 57 ? prev.slice(0, code - 48) + line.slice(1) : line;
    set.add(word);
    prev = word;
  }
  words = set;
  buckets = new Map();
  return words;
}

export function englishWord(word) {
  return load().has(String(word || '').toLowerCase());
}

export function englishExtends(prefix) {
  const lower = String(prefix || '').toLowerCase();
  if (lower.length < 4) return false;
  const set = load();
  const key = lower.slice(0, 2);
  let list = buckets.get(key);
  if (!list) {
    list = [];
    for (const word of set) if (word.startsWith(key)) list.push(word);
    buckets.set(key, list);
  }
  const max = lower.length + 6;
  for (const word of list) {
    if (word.length > lower.length && word.length <= max && word.startsWith(lower)) return true;
  }
  return false;
}
